    /// Текст пустой или состоит из одних пробелов.
    case emptyText
    /// Хранилище не смогло прочитать или записать; подробности только для логов.
    case storage(details: String)
}

/// Правила, общие для любой реализации хранилища.
public enum QuoteRules {
    /// Обрезает пробелы и переводы строк по краям; nil, если ничего не осталось.
    public static func normalizedText(_ raw: String) -> String? {
        let trimmed = raw.trimmingCharacters(in: .whitespacesAndNewlines)
        return trimmed.isEmpty ? nil : trimmed
    }

    /// Новые сверху; при одинаковом времени порядок всё равно стабильный.
    public static func newestFirst(_ a: QuoteItem, _ b: QuoteItem) -> Bool {
        if a.createdAt != b.createdAt { return a.createdAt > b.createdAt }
        return a.id.uuidString > b.id.uuidString
    }
}

/// Хранилище цитат, с которым работают экраны.
public protocol QuoteStore: Sendable {
    /// Сразу отдаёт текущий список цитат книги (новые сверху), затем новый список после каждого
    /// добавления или удаления в этой книге. Заканчивается, когда задача подписчика отменена;
    /// при ошибке чтения заканчивается с `QuoteStoreError`.
    func observeQuotes(ofBook bookID: UUID) async -> AsyncThrowingStream<[QuoteItem], any Error>

    /// Сохраняет цитату с текстом без пробелов по краям. Пустой текст — `.emptyText`.
    @discardableResult
    func addQuote(text: String, toBook bookID: UUID) async throws(QuoteStoreError) -> QuoteItem

    /// Удаляет цитату. Если её уже нет, ничего не делает и не считает это ошибкой.
    func deleteQuote(id: UUID) async throws(QuoteStoreError)
}
```

### 2. Приложение — `Storage/SwiftDataQuoteStore.swift`

```swift
import Foundation
import SwiftData
import SlumpyCore

/// Хранилище цитат на SwiftData. Создаётся один раз на всё приложение: подписчики узнают
/// только об изменениях, прошедших через этот экземпляр.
actor SwiftDataQuoteStore: QuoteStore, ModelActor {
    nonisolated let modelContainer: ModelContainer
    nonisolated let modelExecutor: any ModelExecutor

    private typealias Continuation = AsyncThrowingStream<[QuoteItem], any Error>.Continuation
    private var subscribers: [UUID: (bookID: UUID, continuation: Continuation)] = [:]
    private let now: @Sendable () -> Date

    init(modelContainer: ModelContainer, now: @escaping @Sendable () -> Date = { Date() }) {
        self.modelContainer = modelContainer
        self.modelExecutor = DefaultSerialModelExecutor(modelContext: ModelContext(modelContainer))
        self.now = now
    }

    func observeQuotes(ofBook bookID: UUID) -> AsyncThrowingStream<[QuoteItem], any Error> {
        let (stream, continuation) = AsyncThrowingStream.makeStream(
            of: [QuoteItem].self, throwing: (any Error).self, bufferingPolicy: .bufferingNewest(1))
        do {
            continuation.yield(try fetchQuotes(ofBook: bookID))
        } catch {
            continuation.finish(throwing: error)
            return stream
        }
        let token = UUID()
        subscribers[token] = (bookID, continuation)
        continuation.onTermination = { _ in
            Task { await self.unsubscribe(token) }
        }
        return stream
    }

    @discardableResult
    func addQuote(text: String, toBook bookID: UUID) throws(QuoteStoreError) -> QuoteItem {
        guard let text = QuoteRules.normalizedText(text) else { throw .emptyText }
        let quote = Quote(id: UUID(), text: text, bookID: bookID, createdAt: now())
        modelContext.insert(quote)
        try save()
        publish(toBook: bookID)
        return QuoteItem(quote)
    }

    func deleteQuote(id: UUID) throws(QuoteStoreError) {
        var descriptor = FetchDescriptor<Quote>(predicate: #Predicate { $0.id == id })
        descriptor.fetchLimit = 1
        let found: Quote?
        do {
            found = try modelContext.fetch(descriptor).first
        } catch {
            throw .storage(details: String(describing: error))
        }
        guard let quote = found else { return }
        let bookID = quote.bookID
        modelContext.delete(quote)
        try save()
        publish(toBook: bookID)
    }

    private func fetchQuotes(ofBook bookID: UUID) throws(QuoteStoreError) -> [QuoteItem] {
        let descriptor = FetchDescriptor<Quote>(predicate: #Predicate { $0.bookID == bookID })
        do {
            return try modelContext.fetch(descriptor)
                .map { QuoteItem($0) }
                .sorted(by: QuoteRules.newestFirst)
        } catch {
            throw .storage(details: String(describing: error))
        }
    }

    private func save() throws(QuoteStoreError) {
        do {
            try modelContext.save()
        } catch {
            modelContext.rollback()
            throw .storage(details: String(describing: error))
        }
    }

    private func publish(toBook bookID: UUID) {
        let affected = subscribers.filter { $0.value.bookID == bookID }
        guard !affected.isEmpty else { return }
        do {
            let quotes = try fetchQuotes(ofBook: bookID)
            for subscriber in affected.values { subscriber.continuation.yield(quotes) }
        } catch {
            for (token, subscriber) in affected {
                subscriber.continuation.finish(throwing: error)
                subscribers[token] = nil
            }
        }
    }

    private func unsubscribe(_ token: UUID) {
        subscribers[token] = nil
    }
}

private extension QuoteItem {
    init(_ quote: Quote) {
        self.init(id: quote.id, text: quote.text, bookID: quote.bookID, createdAt: quote.createdAt)
    }
}
```

### 3. Приложение — `Quotes/BookQuotesModel.swift` (логика экрана)

```swift
import Foundation
import Observation
import SlumpyCore

@MainActor @Observable
final class BookQuotesModel {
    let bookID: UUID
    private let store: any QuoteStore

    private(set) var quotes: [QuoteItem] = []
    private(set) var isSaving = false
    private(set) var errorText = ""
    var isShowingError = false
    var draft = ""

    var canAdd: Bool { !isSaving && QuoteRules.normalizedText(draft) != nil }

    init(bookID: UUID, store: any QuoteStore) {
        self.bookID = bookID
        self.store = store
    }

    /// Держит список свежим, пока экран открыт. Вызывать из `.task`.
    func observe() async {
        do {
            for try await items in await store.observeQuotes(ofBook: bookID) {
                quotes = items
            }
        } catch {
            showError("Не удалось загрузить цитаты.")
        }
    }

    func add() async {
        guard canAdd else { return }
        let submitted = draft
        isSaving = true
        defer { isSaving = false }
        do {
            try await store.addQuote(text: submitted, toBook: bookID)
            // Не стираем то, что пользователь успел допечатать во время сохранения.
            if draft == submitted { draft = "" }
        } catch QuoteStoreError.emptyText {
            showError("Цитата пустая.")
        } catch {
            showError("Не удалось сохранить цитату.")
        }
    }

    func delete(_ quote: QuoteItem) async {
        do {
            try await store.deleteQuote(id: quote.id)
        } catch {
            showError("Не удалось удалить цитату.")
        }
    }

    private func showError(_ text: String) {
        errorText = text
        isShowingError = true
    }
}
