import Foundation

/// Хранилище цитат. Экраны знают только этот протокол; реализация (сейчас SwiftData) подставляется при запуске.
///
/// Контракт для любой реализации (проверяется в QuoteStoreContractTests):
/// - методы можно вызывать из любого потока; наружу отдаются только значения `BookQuote`;
/// - `quotes(forBook:)` — цитаты одной книги, новые сверху по `createdAt`;
///   порядок цитат с одинаковым временем не определён;
/// - `add` сохраняет текст после `BookQuote.normalizedText`, пустой отклоняет с `QuoteStoreError.emptyText`;
///   после возврата цитата уже сохранена, при ошибке не сохраняется ничего;
/// - `delete` удаляет цитату; если её уже нет, ничего не делает и не бросает ошибку;
/// - прочие ошибки означают сбой самого хранилища.
public protocol QuoteStore: Sendable {
    func quotes(forBook bookID: UUID) async throws -> [BookQuote]
    func add(text: String, toBook bookID: UUID) async throws -> BookQuote
    func delete(quoteID: UUID) async throws
}
