**`Slumpy/Quotes/SwiftDataQuoteStore.swift`.** Это единственное место, которое знает про SwiftData. При переходе на GRDB рядом появится `GRDBQuoteStore`, а этот файл удалится.
```swift
import Foundation
import SwiftData
import SlumpyCore

/// Хранилище цитат поверх SwiftData. Объекты `Quote` не покидают актор: наружу уходят только `BookQuote`.
actor SwiftDataQuoteStore: ModelActor, QuoteStore {
    nonisolated let modelContainer: ModelContainer
    nonisolated let modelExecutor: any ModelExecutor
    private let now: @Sendable () -> Date

    init(modelContainer: ModelContainer, now: @escaping @Sendable () -> Date = { Date() }) {
        self.modelContainer = modelContainer
        self.modelExecutor = DefaultSerialModelExecutor(modelContext: ModelContext(modelContainer))
        self.now = now
    }

    func quotes(forBook bookID: UUID) throws -> [BookQuote] {
        let descriptor = FetchDescriptor<Quote>(
            predicate: #Predicate { $0.bookID == bookID },
            sortBy: [SortDescriptor(\.createdAt, order: .reverse)]
        )
        return try modelContext.fetch(descriptor).map { BookQuote($0) }
    }

    func add(text: String, toBook bookID: UUID) throws -> BookQuote {
        guard let text = BookQuote.normalizedText(text) else { throw QuoteStoreError.emptyText }
        let quote = Quote(id: UUID(), text: text, bookID: bookID, createdAt: now())
        modelContext.insert(quote)
        try saveOrRollBack()
        return BookQuote(quote)
    }

    func delete(quoteID: UUID) throws {
        let descriptor = FetchDescriptor<Quote>(predicate: #Predicate { $0.id == quoteID })
        for quote in try modelContext.fetch(descriptor) {
            modelContext.delete(quote)
        }
        guard modelContext.hasChanges else { return }
        try saveOrRollBack()
    }

    /// После неудачного сохранения откатываем изменения, чтобы они не сохранились позже вместе с чужой операцией.
    private func saveOrRollBack() throws {
        do {
            try modelContext.save()
        } catch {
            modelContext.rollback()
            throw error
        }
    }
}

private extension BookQuote {
    init(_ quote: Quote) {
        self.init(id: quote.id, bookID: quote.bookID, text: quote.text, createdAt: quote.createdAt)
    }
}
