        .overlay { statusOverlay }
        .task(id: bookID) {
            if model?.bookID != bookID {
                model = BookQuotesModel(bookID: bookID, store: store)
            }
            await model?.reload()
        }
        .alert(problemText, isPresented: problemShown) {
            Button("OK") {}
        }
