            if await model.add(text: submitted), draft == submitted {
                draft = ""
            }
        }
    }

    private var problemShown: Binding<Bool> {
        Binding(
            get: { model?.problem != nil },
            set: { if !$0 { model?.problem = nil } }
        )
    }

    private var problemText: String {
        switch model?.problem {
        case .emptyText: String(localized: "Цитата пустая")
        case .saveFailed: String(localized: "Не удалось сохранить цитату")
        case .deleteFailed: String(localized: "Не удалось удалить цитату")
        case nil: ""
        }
    }
