private func makeStore(_ kind: StoreKind) throws -> any QuoteStore {
    let clock = TickingClock()
    switch kind {
    case .inMemory:
        return InMemoryQuoteStore(now: { clock.next() })
    case .swiftData:
        return SwiftDataQuoteStore(modelContainer: try makeContainer(), now: { clock.next() })
