    @Test
    func swiftDataChangesReachTheDatabase() async throws {
        let container = try makeContainer()
        let clock = TickingClock()
        let writer = SwiftDataQuoteStore(modelContainer: container, now: { clock.next() })
        let added = try await writer.add(text: "Сохранится", toBook: book)

        let reader = SwiftDataQuoteStore(modelContainer: container)
        let afterAdd = try await reader.quotes(forBook: book)
        #expect(afterAdd == [added])

        try await writer.delete(quoteID: added.id)
        let afterDelete = try await reader.quotes(forBook: book)
        #expect(afterDelete.isEmpty)
