import Foundation

/// Цитата из книги — то, с чем работают экраны. Не зависит от способа хранения.
public struct BookQuote: Identifiable, Hashable, Sendable {
    public let id: UUID
    public let bookID: UUID
    public let text: String
    public let createdAt: Date

    public init(id: UUID, bookID: UUID, text: String, createdAt: Date) {
        self.id = id
        self.bookID = bookID
        self.text = text
        self.createdAt = createdAt
    }

    /// Текст в том виде, в каком он сохраняется: без пробелов и переводов строк по краям.
    /// nil, если после этого ничего не осталось.
    public static func normalizedText(_ raw: String) -> String? {
        let trimmed = raw.trimmingCharacters(in: .whitespacesAndNewlines)
        return trimmed.isEmpty ? nil : trimmed
    }
}

public enum QuoteStoreError: Error, Equatable, Sendable {
    /// Текст пустой или состоит из одних пробелов.
    case emptyText
}
