**`SlumpyCore/Quotes/InMemoryQuoteStore.swift`**
```swift
import Foundation

/// Хранилище в памяти: для превью и тестов. Данные пропадают при закрытии приложения.
public actor InMemoryQuoteStore: QuoteStore {
    private var quotesByID: [UUID: BookQuote]
    private let now: @Sendable () -> Date

    public init(quotes: [BookQuote] = [], now: @escaping @Sendable () -> Date = { Date() }) {
        quotesByID = Dictionary(quotes.map { ($0.id, $0) }, uniquingKeysWith: { _, last in last })
        self.now = now
    }

    public func quotes(forBook bookID: UUID) -> [BookQuote] {
        quotesByID.values
            .filter { $0.bookID == bookID }
            .sorted { $0.createdAt > $1.createdAt }
    }

    public func add(text: String, toBook bookID: UUID) throws -> BookQuote {
        guard let text = BookQuote.normalizedText(text) else { throw QuoteStoreError.emptyText }
        let quote = BookQuote(id: UUID(), bookID: bookID, text: text, createdAt: now())
        quotesByID[quote.id] = quote
        return quote
    }

    public func delete(quoteID: UUID) {
        quotesByID[quoteID] = nil
    }
}
