**`Slumpy/Quotes/BookQuotesModel.swift`.** Модель экрана цитат одной книги.
```swift
import Foundation
import Observation
import SlumpyCore

@MainActor
@Observable
final class BookQuotesModel {
    enum Problem: Equatable {
        case emptyText, saveFailed, deleteFailed
    }

    let bookID: UUID
    private(set) var quotes: [BookQuote] = []
    private(set) var hasLoaded = false
    private(set) var loadFailed = false
    private(set) var isAdding = false
    /// Что показать пользователю; экран сбрасывает в nil после показа.
    var problem: Problem?

    private let store: any QuoteStore
    private var reloadGeneration = 0
    private var pendingDeletes: Task<Void, Never>?

    init(bookID: UUID, store: any QuoteStore) {
        self.bookID = bookID
        self.store = store
    }

    func reload() async {
        reloadGeneration += 1
        let generation = reloadGeneration
        // Сначала дожидаемся удалений, иначе свежий список может вернуть только что удалённые строки.
        await pendingDeletes?.value
        do {
            let fresh = try await store.quotes(forBook: bookID)
            // Применяем только самый поздний запрос: более ранний мог вернуться позже со старым списком.
            guard generation == reloadGeneration else { return }
            quotes = fresh
            hasLoaded = true
            loadFailed = false
        } catch {
            guard generation == reloadGeneration else { return }
            // Если список уже был на экране, оставляем его.
            loadFailed = !hasLoaded
        }
    }

    /// true, если цитата сохранена.
    func add(text: String) async -> Bool {
        guard !isAdding else { return false }
        isAdding = true
        defer { isAdding = false }
        do {
            _ = try await store.add(text: text, toBook: bookID)
        } catch QuoteStoreError.emptyText {
            problem = .emptyText
            return false
        } catch {
            problem = .saveFailed
            return false
        }
        await reload()
        return true
    }

    /// Строки исчезают сразу; если удалить не вышло, они вернутся после перечитывания.
    @discardableResult
    func delete(_ doomed: [BookQuote]) -> Task<Void, Never> {
        reloadGeneration += 1
        let ids = doomed.map(\.id)
        quotes.removeAll { ids.contains($0.id) }
        let previous = pendingDeletes
        let deletion = Task {
            await previous?.value
            do {
                for id in ids { try await store.delete(quoteID: id) }
            } catch {
                problem = .deleteFailed
            }
        }
        pendingDeletes = deletion
        return Task {
            await deletion.value
            await reload()
        }
    }
}
```

