**`SlumpyTests/Quotes/QuoteTestSupport.swift`**
```swift
import Foundation
import Synchronization
import SlumpyCore

/// Часы для тестов: каждый вызов на минуту позже предыдущего, чтобы порядок «новые сверху» был однозначным.
final class TickingClock: Sendable {
    private let current = Mutex(Date(timeIntervalSince1970: 1_700_000_000))

    func next() -> Date {
        current.withLock { now in
            now.addTimeInterval(60)
            return now
        }
    }
}

struct TestStoreFailure: Error {}

/// Обёртка над InMemoryQuoteStore для проверки модели экрана:
/// умеет задержать первый ответ со списком и отказать в удалении.
actor ControllableQuoteStore: QuoteStore {
    private let base: InMemoryQuoteStore
    private let failDeletes: Bool
    private var holdNextFetch: Bool
    private var heldFetch: CheckedContinuation<Void, Never>?
    private var holdWaiter: CheckedContinuation<Void, Never>?

    init(holdFirstFetch: Bool = false, failDeletes: Bool = false) {
        let clock = TickingClock()
        base = InMemoryQuoteStore(now: { clock.next() })
        holdNextFetch = holdFirstFetch
        self.failDeletes = failDeletes
    }

    /// Список снимается сразу, а отдаётся только после releaseHeldFetch(): так получается «опоздавший» ответ.
    func quotes(forBook bookID: UUID) async throws -> [BookQuote] {
        let snapshot = await base.quotes(forBook: bookID)
        guard holdNextFetch else { return snapshot }
        holdNextFetch = false
        await withCheckedContinuation { continuation in
            heldFetch = continuation
            holdWaiter?.resume()
            holdWaiter = nil
        }
        return snapshot
    }

    func waitUntilFetchIsHeld() async {
        guard heldFetch == nil else { return }
        await withCheckedContinuation { holdWaiter = $0 }
    }

    func releaseHeldFetch() {
        heldFetch?.resume()
        heldFetch = nil
    }

    func add(text: String, toBook bookID: UUID) async throws -> BookQuote {
        try await base.add(text: text, toBook: bookID)
    }

    func delete(quoteID: UUID) async throws {
        if failDeletes { throw TestStoreFailure() }
        await base.delete(quoteID: quoteID)
    }
}
