import Foundation
import SwiftData

/// The light part of a cover: what a library row needs.
@Model
final class BookCover {
    var thumbnailData: Data = Data()
    /// Changes with every new photo; part of the in-memory cache key.
    var revision: UUID = UUID()
    var book: Book?

    @Relationship(deleteRule: .cascade, inverse: \BookCoverImage.cover)
    var image: BookCoverImage?

    init(thumbnailData: Data) {
        self.thumbnailData = thumbnailData
    }
}

/// Full-size cover for the book screen. A separate model, so the list never loads it.
@Model
final class BookCoverImage {
    @Attribute(.externalStorage) var data: Data = Data()
    var cover: BookCover?

    init(data: Data) {
        self.data = data
    }
}

extension Book {
    func setCover(_ processed: ProcessedCover) {
        guard let context = modelContext else { return }
        let cover: BookCover
        if let existing = self.cover {
            cover = existing
        } else {
            cover = BookCover(thumbnailData: processed.thumbnailData)
            context.insert(cover)
            self.cover = cover
        }
        cover.thumbnailData = processed.thumbnailData
        cover.revision = UUID()
        if let image = cover.image {
            image.data = processed.imageData
        } else {
            let image = BookCoverImage(data: processed.imageData)
            context.insert(image)
            cover.image = image
        }
    }

    func removeCover() {
        guard let cover else { return }
        self.cover = nil
        modelContext?.delete(cover)
    }
}
