import AVFoundation
import PhotosUI
import SwiftData
import SwiftUI

struct BookCoverEditor: View {
    let book: Book

    @Environment(\.openURL) private var openURL

    @State private var isCameraPresented = false
    @State private var isPhotoPickerPresented = false
    @State private var photoItem: PhotosPickerItem?
    @State private var isCameraAccessAlertPresented = false
    @State private var isRemoveConfirmationPresented = false
    @State private var isProcessing = false
    @State private var isSaveErrorPresented = false

    private var isCameraAvailable: Bool {
        UIImagePickerController.isSourceTypeAvailable(.camera)
    }

    var body: some View {
        VStack(spacing: 12) {
            CoverImage(cover: book.cover, size: .full, contentMode: .fit)
                .frame(maxWidth: 220, maxHeight: 330)
                .clipShape(.rect(cornerRadius: 8))
                .overlay {
                    if isProcessing { ProgressView() }
                }
                .accessibilityElement(children: .ignore)
                .accessibilityLabel(book.cover == nil ? "Нет обложки" : "Обложка книги «\(book.title)»")

            Menu {
                if isCameraAvailable {
                    Button("Сфотографировать", systemImage: "camera") {
                        Task { await openCamera() }
                    }
                }
                Button("Выбрать из фото", systemImage: "photo.on.rectangle") {
                    isPhotoPickerPresented = true
                }
                if book.cover != nil {
                    Button("Удалить обложку", systemImage: "trash", role: .destructive) {
                        isRemoveConfirmationPresented = true
                    }
                }
            } label: {
                Label(book.cover == nil ? "Добавить обложку" : "Изменить обложку", systemImage: "camera")
            }
            .disabled(isProcessing)
        }
        .frame(maxWidth: .infinity)
        .fullScreenCover(isPresented: $isCameraPresented) {
            CameraPicker(isPresented: $isCameraPresented) { photo in
                Task { await save { try await CoverImageProcessor.process(photo) } }
            }
            .ignoresSafeArea()
        }
        .photosPicker(isPresented: $isPhotoPickerPresented, selection: $photoItem, matching: .images)
        .onChange(of: photoItem) { _, item in
            guard let item else { return }
            photoItem = nil
            Task {
                await save {
                    guard let data = try await item.loadTransferable(type: Data.self) else {
                        throw CoverProcessingError.unreadableImage
                    }
                    return try await CoverImageProcessor.process(data: data)
                }
            }
        }
        .alert("Нет доступа к камере", isPresented: $isCameraAccessAlertPresented) {
            Button("Открыть настройки") {
                if let url = URL(string: UIApplication.openSettingsURLString) { openURL(url) }
            }
            Button("Отмена", role: .cancel) {}
        } message: {
            Text("Разрешите доступ к камере в Настройках, чтобы фотографировать обложки.")
        }
        .alert("Не удалось сохранить обложку", isPresented: $isSaveErrorPresented) {
            Button("OK", role: .cancel) {}
        } message: {
            Text("Попробуйте ещё раз.")
        }
        .confirmationDialog("Удалить обложку?", isPresented: $isRemoveConfirmationPresented, titleVisibility: .visible) {
            Button("Удалить обложку", role: .destructive) { removeCover() }
        }
    }

    private func openCamera() async {
        switch AVCaptureDevice.authorizationStatus(for: .video) {
        case .authorized:
            isCameraPresented = true
        case .notDetermined:
            if await AVCaptureDevice.requestAccess(for: .video) { isCameraPresented = true }
        default:
            isCameraAccessAlertPresented = true
        }
    }

    private func save(_ makeCover: () async throws -> ProcessedCover) async {
        isProcessing = true
        defer { isProcessing = false }
        guard let processed = try? await makeCover() else {
            isSaveErrorPresented = true
            return
        }
        // The book may have been deleted while the photo was processed.
        guard !book.isDeleted, let context = book.modelContext else { return }
        book.setCover(processed)
        commit(context)
    }

    private func removeCover() {
        guard let context = book.modelContext else { return }
        book.removeCover()
        commit(context)
    }

    /// On failure, rolls back so the screen matches what is stored.
    private func commit(_ context: ModelContext) {
        do {
            try context.save()
        } catch {
            context.rollback()
            isSaveErrorPresented = true
        }
    }
}

struct CameraPicker: UIViewControllerRepresentable {
    @Binding var isPresented: Bool
    let onCapture: (UIImage) -> Void

    func makeUIViewController(context: Context) -> UIImagePickerController {
        let picker = UIImagePickerController()
        picker.sourceType = .camera
        picker.cameraCaptureMode = .photo
        picker.delegate = context.coordinator
        return picker
    }

    func updateUIViewController(_ picker: UIImagePickerController, context: Context) {
        context.coordinator.parent = self
    }

    func makeCoordinator() -> Coordinator {
        Coordinator(parent: self)
    }

    @MainActor
    final class Coordinator: NSObject, UIImagePickerControllerDelegate, UINavigationControllerDelegate {
        var parent: CameraPicker

        init(parent: CameraPicker) {
            self.parent = parent
        }

        func imagePickerController(
            _ picker: UIImagePickerController,
            didFinishPickingMediaWithInfo info: [UIImagePickerController.InfoKey: Any]
        ) {
            if let photo = info[.originalImage] as? UIImage { parent.onCapture(photo) }
            parent.isPresented = false
        }

        func imagePickerControllerDidCancel(_ picker: UIImagePickerController) {
            parent.isPresented = false
        }
    }
}
