## 2. `BookCover.swift` — модели обложки

```swift
import Foundation
import SwiftData

/// The light part of a cover: what a library row needs.
@Model
final class BookCover {
    var thumbnailData: Data = Data()
    /// Changes with every new photo; part of the in-memory cache key.
    var revision: UUID = UUID()
    var book: Book?

    @Relationship(deleteRule: .cascade, inverse: \BookCoverImage.cover)
    var image: BookCoverImage?

    init(thumbnailData: Data) {
        self.thumbnailData = thumbnailData
    }
}

/// Full-size cover for the book screen. A separate model, so the list never loads it.
@Model
final class BookCoverImage {
    @Attribute(.externalStorage) var data: Data = Data()
    var cover: BookCover?

    init(data: Data) {
        self.data = data
    }
}

extension Book {
    func setCover(_ processed: ProcessedCover) {
        guard let context = modelContext else { return }
        let cover: BookCover
        if let existing = self.cover {
            cover = existing
        } else {
            cover = BookCover(thumbnailData: processed.thumbnailData)
            context.insert(cover)
            self.cover = cover
        }
        cover.thumbnailData = processed.thumbnailData
        cover.revision = UUID()
        if let image = cover.image {
            image.data = processed.imageData
        } else {
            let image = BookCoverImage(data: processed.imageData)
            context.insert(image)
            cover.image = image
        }
    }

    func removeCover() {
        guard let cover else { return }
        self.cover = nil
        modelContext?.delete(cover)
    }
}
```

## 3. `CoverImageProcessor.swift` — уменьшение и сжатие фото

```swift
import ImageIO
import UIKit
import UniformTypeIdentifiers

/// Encoded cover, ready to store.
nonisolated struct ProcessedCover: Sendable {
    let imageData: Data
    let thumbnailData: Data
}

nonisolated enum CoverProcessingError: Error {
    case unreadableImage
    case encodingFailed
}

/// Shrinks a camera photo (12 MP, ~48 MB decoded) to a stored cover and a list thumbnail.
/// Runs off the main thread.
nonisolated enum CoverImageProcessor {
    /// Long side in pixels. The book screen shows at most 220×330 pt, ~1000 px on 3x screens.
    static let fullMaxPixels: CGFloat = 1200
    /// List rows show at most 44×66 pt, i.e. 132×198 px on 3x screens.
    static let thumbnailMaxPixels: CGFloat = 300

    @concurrent
    static func process(_ photo: UIImage) async throws -> ProcessedCover {
        try makeCover(from: photo)
    }

    @concurrent
    static func process(data: Data) async throws -> ProcessedCover {
        guard let photo = downsample(data, maxPixels: fullMaxPixels) else {
            throw CoverProcessingError.unreadableImage
        }
        return try makeCover(from: photo)
    }

    private static func makeCover(from photo: UIImage) throws -> ProcessedCover {
        let full = resized(photo, maxPixels: fullMaxPixels)
        let thumbnail = resized(full, maxPixels: thumbnailMaxPixels)
        guard let imageData = encode(full, quality: 0.75),
              let thumbnailData = encode(thumbnail, quality: 0.7) else {
            throw CoverProcessingError.encodingFailed
        }
        return ProcessedCover(imageData: imageData, thumbnailData: thumbnailData)
    }

    /// Redraws upright (camera photos carry a rotation flag), at scale 1, in standard colors.
    private static func resized(_ image: UIImage, maxPixels: CGFloat) -> UIImage {
        let width = image.size.width * image.scale
        let height = image.size.height * image.scale
        let factor = min(1, maxPixels / max(width, height))
        let target = CGSize(width: (width * factor).rounded(), height: (height * factor).rounded())
        let format = UIGraphicsImageRendererFormat()
        format.scale = 1
        format.opaque = true
        format.preferredRange = .standard
        return UIGraphicsImageRenderer(size: target, format: format).image { context in
            UIColor.white.setFill()
            context.fill(CGRect(origin: .zero, size: target))
            image.draw(in: CGRect(origin: .zero, size: target))
        }
    }

    /// Reads a picked file without decoding it at full size.
    private static func downsample(_ data: Data, maxPixels: CGFloat) -> UIImage? {
        let sourceOptions: [CFString: Any] = [kCGImageSourceShouldCache: false]
        guard let source = CGImageSourceCreateWithData(data as CFData, sourceOptions as CFDictionary) else {
            return nil
        }
        let options: [CFString: Any] = [
            kCGImageSourceCreateThumbnailFromImageAlways: true,
            kCGImageSourceCreateThumbnailWithTransform: true,
            kCGImageSourceShouldCacheImmediately: true,
            kCGImageSourceThumbnailMaxPixelSize: maxPixels,
        ]
        guard let cgImage = CGImageSourceCreateThumbnailAtIndex(source, 0, options as CFDictionary) else {
            return nil
        }
        return UIImage(cgImage: cgImage)
    }

    /// HEIC is about half the size of JPEG; JPEG is the fallback where HEIC encoding is missing.
    private static func encode(_ image: UIImage, quality: CGFloat) -> Data? {
        guard let cgImage = image.cgImage else { return nil }
        let properties: [CFString: Any] = [kCGImageDestinationLossyCompressionQuality: quality]
        for type in [UTType.heic, UTType.jpeg] {
            let data = NSMutableData()
            guard let destination = CGImageDestinationCreateWithData(data, type.identifier as CFString, 1, nil) else {
                continue
            }
            CGImageDestinationAddImage(destination, cgImage, properties as CFDictionary)
            if CGImageDestinationFinalize(destination) { return data as Data }
        }
        return nil
    }
}
