```swift
import SwiftUI
import UIKit

/// Decoded covers in memory. NSCache drops them by itself when memory runs low.
@MainActor
final class CoverImageCache {
    static let shared = CoverImageCache()
    private let cache = NSCache<NSString, UIImage>()

    private init() {
        cache.totalCostLimit = 64 * 1024 * 1024
    }

    func image(forKey key: String) -> UIImage? {
        cache.object(forKey: key as NSString)
    }

    func insert(_ image: UIImage, forKey key: String) {
        let cost = image.cgImage.map { $0.bytesPerRow * $0.height }
            ?? Int(image.size.width * image.size.height * image.scale * image.scale * 4)
        cache.setObject(image, forKey: key as NSString, cost: cost)
    }
}

struct CoverImage: View {
    enum Size: String {
        case thumbnail, full
    }

    let cover: BookCover?
    let size: Size
    var contentMode: ContentMode = .fill

    @State private var loaded: UIImage?
    @State private var loadedKey: String?

    var body: some View {
        Group {
            if let image = displayedImage {
                Image(uiImage: image)
                    .resizable()
                    .aspectRatio(contentMode: contentMode)
            } else {
                CoverPlaceholder()
            }
        }
        .task(id: currentKey) { await load() }
        // Only rows on screen hold an image; the rest live in the cache or are reloaded.
        .onDisappear {
            loaded = nil
            loadedKey = nil
        }
    }

    private static func key(_ cover: BookCover, _ size: Size) -> String {
        "\(cover.revision.uuidString)-\(size.rawValue)"
    }

    private var currentKey: String? {
        cover.map { Self.key($0, size) }
    }

    private var displayedImage: UIImage? {
        guard let cover else { return nil }
        let key = Self.key(cover, size)
        if loadedKey == key, let loaded { return loaded }
        if let cached = CoverImageCache.shared.image(forKey: key) { return cached }
        // While the full cover loads, show the thumbnail if it is already decoded.
        return size == .full ? CoverImageCache.shared.image(forKey: Self.key(cover, .thumbnail)) : nil
    }

    private func load() async {
        guard let cover else { return }
        let key = Self.key(cover, size)
        if let cached = CoverImageCache.shared.image(forKey: key) {
            loaded = cached
            loadedKey = key
            return
        }
        let data: Data? = size == .thumbnail ? cover.thumbnailData : cover.image?.data
        guard let data, let image = UIImage(data: data) else { return }
        let prepared = await image.byPreparingForDisplay() ?? image
        guard !Task.isCancelled else { return }
        CoverImageCache.shared.insert(prepared, forKey: key)
        loaded = prepared
        loadedKey = key
    }
}

struct CoverPlaceholder: View {
    var body: some View {
        Rectangle()
            .fill(.quaternary)
            .overlay {
                Image(systemName: "book.closed")
                    .imageScale(.large)
                    .foregroundStyle(.secondary)
            }
            .aspectRatio(2.0 / 3.0, contentMode: .fit)
    }
}

/// Cover for a library row.
struct BookCoverThumbnail: View {
    let book: Book
    @ScaledMetric(relativeTo: .body) private var scaledWidth: CGFloat = 44

    /// Capped so the 300 px thumbnail stays sharp at the largest text sizes.
    private var width: CGFloat { min(scaledWidth, 66) }

    var body: some View {
        CoverImage(cover: book.cover, size: .thumbnail)
            .frame(width: width, height: width * 1.5)
            .clipShape(.rect(cornerRadius: 4))
            .accessibilityHidden(true)
