### 2. `CoverProcessor.swift`: уменьшение и сжатие фото

```swift
import UIKit
import ImageIO
import UniformTypeIdentifiers

nonisolated struct ProcessedCover: Sendable {
    let thumbnail: Data
    let full: Data
}

nonisolated enum CoverProcessor {
    /// Хватает для экрана книги на любом iPhone.
    static let fullMaxSide: CGFloat = 1200
    /// Строка списка ~44–80 pt шириной при @3x.
    static let thumbnailMaxSide: CGFloat = 240

    /// Работает вне главного потока: 12-мегапиксельное фото обрабатывается ~0,2–0,5 с.
    static func process(_ photo: UIImage) async -> ProcessedCover? {
        await Task.detached(priority: .userInitiated) {
            autoreleasepool { makeCover(from: photo) }
        }.value
    }

    static func makeCover(from photo: UIImage) -> ProcessedCover? {
        guard let full = resized(photo, maxSide: fullMaxSide),
              let thumbnail = resized(full, maxSide: thumbnailMaxSide),
              // HEIC вдвое меньше JPEG; если кодировщика нет (бывает в симуляторе) — JPEG.
              let fullData = encode(full, as: .heic, quality: 0.7) ?? encode(full, as: .jpeg, quality: 0.8),
              // Миниатюры в JPEG: при прокрутке он декодируется быстрее HEIC.
              let thumbnailData = encode(thumbnail, as: .jpeg, quality: 0.75)
        else { return nil }
        return ProcessedCover(thumbnail: thumbnailData, full: fullData)
    }

    /// Уменьшает картинку (не увеличивает) и «впекает» поворот камеры в пиксели.
    private static func resized(_ image: UIImage, maxSide: CGFloat) -> UIImage? {
        let pixelWidth = image.size.width * image.scale
        let pixelHeight = image.size.height * image.scale
        let longest = max(pixelWidth, pixelHeight)
        guard longest > 0 else { return nil }

        let factor = min(1, maxSide / longest)
        let target = CGSize(width: (pixelWidth * factor).rounded(), height: (pixelHeight * factor).rounded())

        let format = UIGraphicsImageRendererFormat()
        format.scale = 1
        format.opaque = true
        format.preferredRange = .standard
        return UIGraphicsImageRenderer(size: target, format: format).image { _ in
            image.draw(in: CGRect(origin: .zero, size: target))
        }
    }

    private static func encode(_ image: UIImage, as type: UTType, quality: CGFloat) -> Data? {
        guard let cgImage = image.cgImage else { return nil }
        let data = NSMutableData()
        guard let destination = CGImageDestinationCreateWithData(data, type.identifier as CFString, 1, nil) else {
            return nil
        }
        let options = [kCGImageDestinationLossyCompressionQuality: quality] as CFDictionary
        CGImageDestinationAddImage(destination, cgImage, options)
        guard CGImageDestinationFinalize(destination) else { return nil }
        return data as Data
    }
}
```

