    @MainActor
    private func deleteCoverRecords(in context: ModelContext) {
        if let coverThumbnail { context.delete(coverThumbnail) }
        if let coverImage { context.delete(coverImage) }
        coverThumbnail = nil
        coverImage = nil
    }
