```swift
import SwiftUI
import UIKit

/// Готовые к показу картинки. Лимит по памяти; при нехватке памяти система чистит кэш сама.
@MainActor
final class CoverImageCache {
    static let shared = CoverImageCache()

    private let cache = NSCache<NSUUID, UIImage>()

    private init() {
        cache.totalCostLimit = 50 * 1024 * 1024
    }

    func image(for key: UUID) -> UIImage? {
        cache.object(forKey: key as NSUUID)
    }

    func insert(_ image: UIImage, for key: UUID) {
        let bytes = image.size.width * image.scale * image.size.height * image.scale * 4
        cache.setObject(image, forKey: key as NSUUID, cost: Int(bytes))
    }
}

/// Обложка в рамке 2:3. Данные читаются только когда строка видна, декодируются в фоне.
struct CoverImageView: View {
    let key: UUID?
    let loadData: @MainActor () -> Data?

    @State private var image: UIImage?

    init(key: UUID?, loadData: @escaping @MainActor () -> Data?) {
        self.key = key
        self.loadData = loadData
        // Из кэша — сразу, без мигания заглушки при возврате к списку.
        _image = State(initialValue: key.flatMap { CoverImageCache.shared.image(for: $0) })
    }

    var body: some View {
        Color.clear
            .aspectRatio(2.0 / 3.0, contentMode: .fit)
            .overlay {
                if let image {
                    Image(uiImage: image)
                        .resizable()
                        .scaledToFill()
                } else {
                    CoverPlaceholder()
                }
            }
            .clipShape(.rect(cornerRadius: 6))
            .task(id: key) { await load() }
    }

    private func load() async {
        guard let key else {
            image = nil
            return
        }
        if let cached = CoverImageCache.shared.image(for: key) {
            image = cached
            return
        }
        guard let data = loadData() else { return }
        let decoded = await Task.detached(priority: .userInitiated) {
            UIImage(data: data)?.preparingForDisplay()
        }.value
        guard let decoded else { return }
        CoverImageCache.shared.insert(decoded, for: key)
        guard !Task.isCancelled else { return }
        image = decoded
    }
}

private struct CoverPlaceholder: View {
    var body: some View {
        Rectangle()
            .fill(.quaternary)
            .overlay {
                Image(systemName: "book.closed")
                    .font(.title3)
                    .foregroundStyle(.secondary)
            }
    }
}
