### 7. `BookDetailView.swift`: экран книги

```swift
import SwiftUI
import SwiftData
import UIKit

struct BookDetailView: View {
    let book: Book

    @Environment(\.modelContext) private var modelContext
    @Environment(\.openURL) private var openURL
    @State private var showsCamera = false
    @State private var showsCameraDenied = false
    @State private var showsRemoveConfirmation = false
    @State private var showsSaveError = false
    @State private var isProcessing = false

    var body: some View {
        ScrollView {
            VStack(spacing: 16) {
                CoverImageView(key: book.coverImage?.id) { book.coverImage?.data }
                    .frame(maxWidth: 240)
                    .overlay {
                        if isProcessing { ProgressView() }
                    }
                    .accessibilityLabel(book.coverImage == nil ? "Нет обложки" : "Обложка книги «\(book.title)»")

                VStack(spacing: 4) {
                    Text(book.title)
                        .font(.title2.bold())
                    Text(book.author)
                        .foregroundStyle(.secondary)
                }
                .multilineTextAlignment(.center)

                coverButtons
            }
            .padding()
        }
        .navigationBarTitleDisplayMode(.inline)
        .fullScreenCover(isPresented: $showsCamera) {
            CameraPicker { photo in
                Task { await saveCover(from: photo) }
            }
            .ignoresSafeArea()
        }
        .alert("Нет доступа к камере", isPresented: $showsCameraDenied) {
            Button("Открыть настройки") {
                if let url = URL(string: UIApplication.openSettingsURLString) { openURL(url) }
            }
            Button("Отмена", role: .cancel) {}
        } message: {
            Text("Разрешите доступ к камере в Настройках, чтобы сфотографировать обложку.")
        }
        .alert("Не удалось сохранить обложку", isPresented: $showsSaveError) {
            Button("OK", role: .cancel) {}
        }
        .confirmationDialog("Удалить обложку?", isPresented: $showsRemoveConfirmation, titleVisibility: .visible) {
            Button("Удалить", role: .destructive) { removeCover() }
        }
    }

    @ViewBuilder
    private var coverButtons: some View {
        if CameraAccess.isAvailable {
            Button(
                book.coverImage == nil ? "Сфотографировать обложку" : "Переснять обложку",
                systemImage: "camera"
            ) {
                Task { await openCamera() }
            }
            .buttonStyle(.borderedProminent)
            .disabled(isProcessing)
        }
        if book.coverImage != nil {
            Button("Удалить обложку", systemImage: "trash", role: .destructive) {
                showsRemoveConfirmation = true
            }
            .disabled(isProcessing)
        }
    }

    private func openCamera() async {
        if await CameraAccess.request() {
            showsCamera = true
        } else {
            showsCameraDenied = true
        }
    }

    private func saveCover(from photo: UIImage) async {
        isProcessing = true
        defer { isProcessing = false }
        guard let cover = await CoverProcessor.process(photo) else {
            showsSaveError = true
            return
        }
        // Книгу могли удалить, пока шла обработка.
        guard !book.isDeleted, book.modelContext != nil else { return }
        do {
            try book.setCover(cover, in: modelContext)
        } catch {
            showsSaveError = true
        }
    }

    private func removeCover() {
        do {
            try book.removeCover(in: modelContext)
        } catch {
            showsSaveError = true
        }
    }
}
```

Если `modelContainer` в приложении объявлен списком моделей, добавьте в него новые: `.modelContainer(for: [Book.self, CoverThumbnail.self, CoverImage.self])`.

