## 1. Формирование CSV (общий модуль логики, только Foundation)

```swift
// ReadingHistoryCSV.swift
import Foundation

/// Собирает CSV с историей чтения для Excel и Numbers.
public enum ReadingHistoryCSV {

    public struct Row: Sendable, Equatable {
        public var startedAt: Date
        public var duration: TimeInterval
        public var timeZoneIdentifier: String
        public var bookTitle: String
        public var bookAuthor: String

        public init(
            startedAt: Date,
            duration: TimeInterval,
            timeZoneIdentifier: String,
            bookTitle: String,
            bookAuthor: String
        ) {
            self.startedAt = startedAt
            self.duration = duration
            self.timeZoneIdentifier = timeZoneIdentifier
            self.bookTitle = bookTitle
            self.bookAuthor = bookAuthor
        }
    }

    public enum Delimiter: String, Sendable {
        case comma = ","
        case semicolon = ";"

        /// Excel берёт разделитель из региональных настроек: где дробная часть
        /// пишется через запятую (Россия, Европа), он ждёт точку с запятой.
        public static func matching(_ locale: Locale) -> Delimiter {
            locale.decimalSeparator == "," ? .semicolon : .comma
        }
    }

    public static let header = ["Начало", "Длительность (мин)", "Название", "Автор"]

    /// Готовое содержимое файла: UTF-8 с BOM, чтобы Excel не ломал кириллицу.
    public static func fileData(
        rows: [Row],
        delimiter: Delimiter,
        fallbackTimeZone: TimeZone = .current
    ) -> Data {
        var data = Data([0xEF, 0xBB, 0xBF])
        data.append(contentsOf: text(rows: rows, delimiter: delimiter, fallbackTimeZone: fallbackTimeZone).utf8)
        return data
    }

    public static func text(
        rows: [Row],
        delimiter: Delimiter,
        fallbackTimeZone: TimeZone = .current
    ) -> String {
        let headerLine = header.map(textField)
        let rowLines = rows
            .sorted { $0.startedAt < $1.startedAt }
            .map { row in
                [
                    startText(row, fallbackTimeZone: fallbackTimeZone),
                    String(minutes(row.duration)),
                    textField(row.bookTitle),
                    textField(row.bookAuthor),
                ]
            }
        return ([headerLine] + rowLines)
            .map { $0.joined(separator: delimiter.rawValue) }
            .joined(separator: "\r\n") + "\r\n"
    }

    /// «История чтения 2026-10-28.csv»
    public static func fileName(exportedAt date: Date, timeZone: TimeZone = .current) -> String {
        "История чтения \(dateTimeText(date, timeZone: timeZone, includeTime: false)).csv"
    }

    // MARK: - Поля

    /// Местное время там, где человек читал, в виде «2026-10-28 21:05».
    /// Такую запись Excel и Numbers распознают как дату при любых региональных настройках.
    static func startText(_ row: Row, fallbackTimeZone: TimeZone) -> String {
        let timeZone = TimeZone(identifier: row.timeZoneIdentifier) ?? fallbackTimeZone
        return dateTimeText(row.startedAt, timeZone: timeZone, includeTime: true)
    }

    /// Целые минуты, округление к ближайшему.
    static func minutes(_ duration: TimeInterval) -> Int {
        guard duration.isFinite, duration > 0 else { return 0 }
        return Int(min(duration / 60, Double(Int32.max)).rounded())
    }

    /// Текстовая ячейка по RFC 4180: кавычки удваиваются, а ячейка, где есть
    /// запятая, точка с запятой, кавычка или перенос строки, берётся в кавычки.
    /// Если текст начинается с символа, который Excel принял бы за формулу,
    /// перед ним ставится апостроф.
    static func textField(_ value: String) -> String {
        var value = value
        if let first = value.first, "=+-@\t\r".contains(first) {
            value = "'" + value
        }
        let needsQuotes = value.contains { ",;\"\r\n".contains($0) }
        guard needsQuotes else { return value }
        return "\"" + value.replacingOccurrences(of: "\"", with: "\"\"") + "\""
    }

    private static func dateTimeText(_ date: Date, timeZone: TimeZone, includeTime: Bool) -> String {
        var calendar = Calendar(identifier: .gregorian)
        calendar.timeZone = timeZone
        let c = calendar.dateComponents([.year, .month, .day, .hour, .minute], from: date)
        let day = String(format: "%04d-%02d-%02d", c.year ?? 0, c.month ?? 0, c.day ?? 0)
        guard includeTime else { return day }
        return day + String(format: " %02d:%02d", c.hour ?? 0, c.minute ?? 0)
    }
}
```

