## Файл 1. `ReadingHistoryCSV.swift`: сборка таблицы

Этот файл использует только Foundation, без SwiftUI, поэтому его можно положить в общий модуль с логикой.

```swift
import Foundation

/// Одна строка экспорта: только те значения, которые попадают в файл.
public struct ReadingHistoryRow: Sendable, Equatable {
    public var startedAt: Date
    public var duration: TimeInterval
    public var timeZoneIdentifier: String
    public var bookTitle: String
    public var bookAuthor: String

    public init(
        startedAt: Date,
        duration: TimeInterval,
        timeZoneIdentifier: String,
        bookTitle: String,
        bookAuthor: String
    ) {
        self.startedAt = startedAt
        self.duration = duration
        self.timeZoneIdentifier = timeZoneIdentifier
        self.bookTitle = bookTitle
        self.bookAuthor = bookAuthor
    }
}

public enum ReadingHistoryCSV {
    /// Собирает CSV, который Excel и Numbers открывают без мастера импорта.
    /// - Parameter locale: определяет разделитель полей. Где десятичный разделитель — запятая
    ///   (ru, de, fr…), Excel ждёт `;`, иначе `,`.
    public static func make(rows: [ReadingHistoryRow], locale: Locale = .current) -> String {
        let separator = locale.decimalSeparator == "," ? ";" : ","
        var formatters: [String: DateFormatter] = [:]

        var lines: [String] = []
        lines.append(
            ["Начало", "Длительность, мин", "Название", "Автор"]
                .map(textField)
                .joined(separator: separator)
        )

        for row in rows.sorted(by: { $0.startedAt < $1.startedAt }) {
            let formatter: DateFormatter
            if let cached = formatters[row.timeZoneIdentifier] {
                formatter = cached
            } else {
                formatter = makeDateFormatter(timeZoneIdentifier: row.timeZoneIdentifier)
                formatters[row.timeZoneIdentifier] = formatter
            }

            lines.append(
                [
                    formatter.string(from: row.startedAt),
                    String(minutes(row.duration)),
                    textField(row.bookTitle),
                    textField(row.bookAuthor),
                ]
                .joined(separator: separator)
            )
        }

        // BOM нужен, чтобы Excel прочитал файл как UTF-8, а не как Windows-1251.
        return "\u{FEFF}" + lines.joined(separator: "\r\n") + "\r\n"
    }

    /// Дата и время по часам того места, где шла сессия, в формате, который Excel и Numbers
    /// распознают как дату при любом языке системы.
    private static func makeDateFormatter(timeZoneIdentifier: String) -> DateFormatter {
        let formatter = DateFormatter()
        formatter.locale = Locale(identifier: "en_US_POSIX")
        formatter.calendar = Calendar(identifier: .gregorian)
        formatter.timeZone = TimeZone(identifier: timeZoneIdentifier) ?? .current
        formatter.dateFormat = "yyyy-MM-dd HH:mm"
        return formatter
    }

    private static func minutes(_ duration: TimeInterval) -> Int {
        guard duration.isFinite, duration > 0 else { return 0 }
        return Int((duration / 60).rounded())
    }

    /// Текст всегда в кавычках, внутренние кавычки удваиваются (RFC 4180), поэтому запятые,
    /// точки с запятой, кавычки и переносы строк в названии не ломают колонки.
    private static func textField(_ text: String) -> String {
        var value = text
        // Текст, начинающийся с = + - @, Excel выполнит как формулу; апостроф делает его текстом.
        if let first = value.unicodeScalars.first, "=+-@\t\r".unicodeScalars.contains(first) {
            value = "'" + value
        }
        return "\"" + value.replacingOccurrences(of: "\"", with: "\"\"") + "\""
    }
}
```

