        self.rows = rows
    }

    public static var transferRepresentation: some TransferRepresentation {
        FileRepresentation(exportedContentType: .commaSeparatedText) { export in
            SentTransferredFile(try export.writeFile())
        }
    }

    func writeFile() throws -> URL {
        // Отдельная папка на каждый экспорт: имя файла остаётся красивым и не конфликтует.
        let directory = FileManager.default.temporaryDirectory
            .appending(path: UUID().uuidString, directoryHint: .isDirectory)
        try FileManager.default.createDirectory(at: directory, withIntermediateDirectories: true)

        let day = Date.now.formatted(.iso8601.year().month().day())
        let file = directory.appending(path: "Slumpy — история чтения \(day).csv")
        try Data(ReadingHistoryCSV.make(rows: rows).utf8).write(to: file, options: .atomic)
        return file
    }
