## 1. Кеш обложек: `CoverCache.swift`

```swift
import UIKit

/// Тип id книги. Если в проекте id не строка (например, UUID или Int),
/// поменяйте только эту строку и ключ в `memory` (см. допущения).
typealias BookID = String

/// Кеш обложек: память → диск, без повторной загрузки одной обложки.
actor CoverCache {
    static let shared = CoverCache()

    private let loadFromDisk: @Sendable (BookID) async throws -> UIImage
    /// Готовые обложки. Система сама освобождает их, когда не хватает памяти.
    private let memory = NSCache<NSString, UIImage>()
    /// Обложки, которые грузятся прямо сейчас. Все, кто попросил ту же обложку, ждут одну загрузку.
    private var inFlight: [BookID: Task<UIImage, any Error>] = [:]

    init(
        loadFromDisk: @escaping @Sendable (BookID) async throws -> UIImage = { id in
            try await loadCoverFromDisk(id: id)
        }
    ) {
        self.loadFromDisk = loadFromDisk
        memory.totalCostLimit = 100 * 1024 * 1024 // около 100 МБ картинок
    }

    func cover(for id: BookID) async throws -> UIImage {
        if let image = memory.object(forKey: id as NSString) {
            return image
        }
        if let running = inFlight[id] {
            return try await running.value
        }
        // Загрузка регистрируется до первого `await`, поэтому второй запрос
        // увидит её в `inFlight` и не начнёт свою.
        let task = Task { try await self.load(id) }
        inFlight[id] = task
        return try await task.value
    }

    private func load(_ id: BookID) async throws -> UIImage {
        defer { inFlight[id] = nil }
        let image = try await loadFromDisk(id)
        memory.setObject(image, forKey: id as NSString, cost: image.estimatedByteCount)
        return image
    }
}

private extension UIImage {
    /// Примерный размер картинки в памяти: по нему кеш решает, что выбросить.
    var estimatedByteCount: Int {
        if let cgImage {
            return cgImage.bytesPerRow * cgImage.height
        }
        return Int(size.width * scale * size.height * scale * 4)
    }
}
```

## 2. Как экран берёт обложку: `BookCoverView.swift`

```swift
import SwiftUI

struct BookCoverView: View {
    let bookID: BookID
    @State private var image: UIImage?

    var body: some View {
        Group {
            if let image {
                Image(uiImage: image)
                    .resizable()
                    .scaledToFit()
            } else {
                Rectangle()
                    .fill(.secondary.opacity(0.2))
            }
        }
        .task(id: bookID) {
            image = nil
            let loaded = try? await CoverCache.shared.cover(for: bookID)
            // Если экран за это время показал другую книгу, старая обложка не подставится.
            if !Task.isCancelled {
                image = loaded
            }
        }
    }
}
```

## 3. Тест: `CoverCacheTests.swift`

```swift
import Testing
import UIKit
@testable import Slumpy

private actor LoadCounter {
    private(set) var count = 0
    func increment() { count += 1 }
}

private struct DiskError: Error {}

@Test func simultaneousRequestsLoadFromDiskOnce() async throws {
    let counter = LoadCounter()
    let cache = CoverCache { _ in
        await counter.increment()
        try await Task.sleep(for: .milliseconds(100)) // медленный диск
        return UIImage()
    }

    try await withThrowingTaskGroup(of: UIImage.self) { group in
        for _ in 0..<10 {
            group.addTask { try await cache.cover(for: "book-1") }
        }
        try await group.waitForAll()
    }
    _ = try await cache.cover(for: "book-1") // повторный запрос берётся из памяти

    #expect(await counter.count == 1)
}

@Test func failedLoadIsRetriedOnNextRequest() async throws {
    let counter = LoadCounter()
    let cache = CoverCache { _ in
        await counter.increment()
        if await counter.count == 1 { throw DiskError() }
        return UIImage()
    }

    await #expect(throws: DiskError.self) { try await cache.cover(for: "book-1") }
    _ = try await cache.cover(for: "book-1")

    #expect(await counter.count == 2)
}
