    ) {
        self.loadFromDisk = loadFromDisk
        memory.totalCostLimit = 100 * 1024 * 1024 // около 100 МБ картинок
    }

    func cover(for id: BookID) async throws -> UIImage {
        if let image = memory.object(forKey: id as NSString) {
            return image
        }
        if let running = inFlight[id] {
            return try await running.value
        }
        // Загрузка регистрируется до первого `await`, поэтому второй запрос
        // увидит её в `inFlight` и не начнёт свою.
        let task = Task { try await self.load(id) }
        inFlight[id] = task
        return try await task.value
    }

    private func load(_ id: BookID) async throws -> UIImage {
        defer { inFlight[id] = nil }
        let image = try await loadFromDisk(id)
        memory.setObject(image, forKey: id as NSString, cost: image.estimatedByteCount)
        return image
    }
}

private extension UIImage {
    /// Примерный размер картинки в памяти: по нему кеш решает, что выбросить.
    var estimatedByteCount: Int {
        if let cgImage {
            return cgImage.bytesPerRow * cgImage.height
        }
        return Int(size.width * scale * size.height * scale * 4)
    }
}
```

