## 1. Кеш обложек — `CoverCache.swift` (в приложении)

```swift
import UIKit

/// Тип id книги. Если в проекте id не строка (например, UUID или Int), поменять здесь.
typealias BookID = String

/// Общий кеш обложек. Одну и ту же обложку с диска одновременно грузит только одна загрузка,
/// остальные запросившие ждут её результат.
actor CoverCache {
    static let shared = CoverCache()

    private let loader: @Sendable (BookID) async throws -> UIImage
    /// Готовые обложки. При нехватке памяти система сама вытесняет часть из них.
    private let images = NSCache<NSString, UIImage>()
    /// Загрузки, которые идут прямо сейчас.
    private var inFlight: [BookID: Task<UIImage, any Error>] = [:]

    init(
        countLimit: Int = 200,
        loader: @escaping @Sendable (BookID) async throws -> UIImage = { try await loadCoverFromDisk(id: $0) }
    ) {
        images.countLimit = countLimit
        self.loader = loader
    }

    func cover(for id: BookID) async throws -> UIImage {
        let key = String(describing: id) as NSString

        if let image = images.object(forKey: key) {
            return image
        }
        if let running = inFlight[id] {
            return try await running.value
        }

        // Проверка выше и запись ниже идут без await между ними, поэтому второй запрос
        // гарантированно увидит эту загрузку и присоединится к ней.
        let loader = self.loader
        let task = Task.detached(priority: .userInitiated) {
            try await loader(id)
        }
        inFlight[id] = task

        do {
            let image = try await task.value
            images.setObject(image, forKey: key)
            inFlight[id] = nil
            return image
        } catch {
            inFlight[id] = nil  // ошибку не запоминаем: следующий запрос попробует снова
            throw error
        }
    }
}
```

