### Расширение DeviceActivityMonitor: `SlumpyDeviceActivityMonitor.swift`

Если в расширении уже есть свой класс, перенесите в него метод `intervalDidEnd`.

```swift
import DeviceActivity
import Foundation
import SlumpyCore

/// Система вызывает это расширение в конце интервала, даже если приложение выгружено.
final class SlumpyDeviceActivityMonitor: DeviceActivityMonitor {
    override func intervalDidEnd(for activity: DeviceActivityName) {
        super.intervalDidEnd(for: activity)
        guard let sessionID = ReadingMonitor.sessionID(from: activity) else { return }
        // Журнал не прочитался — всё равно снимаем: зависшая блокировка хуже, чем снятая раньше.
        let log = try? SessionLogStore.shared()?.load()
        if log?.shouldClearShield(whenIntervalEndsFor: sessionID, at: .now) ?? true {
            ReadingShield.clear()
        }
    }
}
```

### Приложение: `ReadingSessionController.swift`

Ваш текущий код блокировки нужно заменить на `start(blocking:)`. Иначе блокировка окажется в другом хранилище, и расширение её не снимет.

```swift
import ActivityKit
import DeviceActivity
import FamilyControls
import Foundation
import ManagedSettings
import Observation
import os
import SlumpyCore

enum ReadingSessionError: Error {
    case storageUnavailable
    case durationTooShort
}

/// Начало, досрочная остановка и завершение сессии чтения.
/// `reconcile()` можно вызывать сколько угодно раз: итог одинаковый.
@MainActor
@Observable
final class ReadingSessionController {
    /// Короче 15 минут система не принимает расписание, а без него блокировку в фоне снять некому.
    static let minimumDuration: TimeInterval = 15 * 60

    private(set) var log = SessionLog()
    /// Что Slumpy должен сказать сейчас.
    private(set) var announcement: String?

    @ObservationIgnored private let store: SessionLogStore?
    @ObservationIgnored private let now: () -> Date
    @ObservationIgnored private var isLoaded = false
    @ObservationIgnored private var endTimer: Task<Void, Never>?
    @ObservationIgnored private let logger = Logger(subsystem: "app.slumpy", category: "reading-session")

    init(store: SessionLogStore? = SessionLogStore.shared(), now: @escaping () -> Date = { .now }) {
        self.store = store
        self.now = now
        loadIfNeeded()
    }

    var runningSession: ReadingSession? { log.runningSession(at: now()) }

    var minutesReadToday: Int {
        let current = now()
        return log.minutesRead(onDayOf: current, calendar: .current, now: current)
    }

    func start(blocking selection: FamilyActivitySelection, duration: TimeInterval = 30 * 60) throws {
        guard duration >= Self.minimumDuration else { throw ReadingSessionError.durationTooShort }
        loadIfNeeded()
        guard let store, isLoaded else { throw ReadingSessionError.storageUnavailable }
        let session = ReadingSession(startedAt: now(), plannedDuration: duration)
        var updated = log
        guard updated.begin(session) else { return }

        // Порядок важен: расписание для расширения, запись, и только потом блокировка.
        // Сбой на любом шаге оставляет либо телефон без блокировки, либо блокировку, которую снимет расширение.
        try startMonitoring(session)
        do {
            try store.save(updated)
        } catch {
            DeviceActivityCenter().stopMonitoring([ReadingMonitor.name(for: session.id)])
            throw error
        }
        log = updated
        applyShield(selection)
        startLiveActivity(for: session)
        scheduleEndTimer(for: session)
    }

    func stop() async throws {
        loadIfNeeded()
        guard let store, let session = runningSession else { return }
        var updated = log
        updated.stop(sessionID: session.id, at: now())
        // Не записали — не снимаем: иначе после перезапуска сессия засчиталась бы целиком.
        // Блокировку в любом случае снимет расширение в конце сессии.
        try store.save(updated)
        log = updated
        endTimer?.cancel()
        endTimer = nil
        await tearDown()
    }

    /// Вызывается при каждом открытии приложения и в момент окончания сессии.
    func reconcile() async {
        loadIfNeeded()
        guard isLoaded else { return }
        let current = now()
        if let running = log.runningSession(at: current) {
            scheduleEndTimer(for: running)
            return
        }
        endTimer?.cancel()
        endTimer = nil
        if let finished = log.pendingAnnouncement(at: current) {
            announcement = "Сессия окончена"
            var updated = log
            updated.markAnnounced(sessionID: finished.id, at: current)
            do {
                try store?.save(updated)
                log = updated
            } catch {
                // Не записали — Slumpy повторит фразу в следующий раз; это лучше, чем промолчать.
                logger.error("Не удалось отметить реплику: \(error.localizedDescription)")
            }
        }
        await tearDown()
    }

    func dismissAnnouncement() { announcement = nil }

    private func loadIfNeeded() {
        guard !isLoaded else { return }
        guard let store else {
            isLoaded = true
            return
        }
        do {
            log = try store.load()
            isLoaded = true
        } catch is DecodingError {
            store.moveAsideUnreadableFile()
            isLoaded = true
        } catch {
            // Файл временно недоступен (телефон не разблокирован после перезагрузки) — попробуем в следующий раз.
            logger.error("Журнал сессий недоступен: \(error.localizedDescription)")
        }
    }

    private func applyShield(_ selection: FamilyActivitySelection) {
        let shieldStore = ManagedSettingsStore(named: .readingSession)
        shieldStore.shield.applications = selection.applicationTokens.isEmpty ? nil : selection.applicationTokens
        shieldStore.shield.applicationCategories = selection.categoryTokens.isEmpty ? nil : .specific(selection.categoryTokens)
        shieldStore.shield.webDomains = selection.webDomainTokens.isEmpty ? nil : selection.webDomainTokens
    }

    private func startMonitoring(_ session: ReadingSession) throws {
        let center = DeviceActivityCenter()
        center.stopMonitoring(center.activities.filter { ReadingMonitor.sessionID(from: $0) != nil })
        // Полная дата, а не только время: система не перепутает день, в том числе после полуночи.
        let parts: Set<Calendar.Component> = [.year, .month, .day, .hour, .minute, .second]
        let calendar = Calendar.current
        let schedule = DeviceActivitySchedule(
            intervalStart: calendar.dateComponents(parts, from: session.startedAt),
            intervalEnd: calendar.dateComponents(parts, from: session.endsAt),
            repeats: false
        )
        try center.startMonitoring(ReadingMonitor.name(for: session.id), during: schedule)
    }

    private func startLiveActivity(for session: ReadingSession) {
        guard ActivityAuthorizationInfo().areActivitiesEnabled else { return }
        let attributes = ReadingActivityAttributes(startedAt: session.startedAt, endsAt: session.endsAt)
        // staleDate = конец сессии: карточка сама переключится на «Сессия окончена», даже если приложение выгружено.
        let content = ActivityContent(
            state: ReadingActivityAttributes.ContentState(isFinished: false),
            staleDate: session.endsAt
        )
        do {
            _ = try Activity.request(attributes: attributes, content: content, pushType: nil)
        } catch {
            // Сессия работает и без карточки.
            logger.error("Live Activity не запустилась: \(error.localizedDescription)")
        }
    }

    private func scheduleEndTimer(for session: ReadingSession) {
        endTimer?.cancel()
        let delay = max(0, session.endsAt.timeIntervalSince(now()))
        endTimer = Task { [weak self] in
            try? await Task.sleep(for: .seconds(delay))
            guard !Task.isCancelled, let self else { return }
            // Обнуляем до reconcile: иначе он отменил бы задачу, в которой сам выполняется.
            endTimer = nil
            await reconcile()
        }
    }

    private func tearDown() async {
        ReadingShield.clear()
        let center = DeviceActivityCenter()
        center.stopMonitoring(center.activities.filter { ReadingMonitor.sessionID(from: $0) != nil })
        await Self.endAllLiveActivities()
    }

    @concurrent
    nonisolated private static func endAllLiveActivities() async {
        for activity in Activity<ReadingActivityAttributes>.activities {
            let finalContent = ActivityContent(
                state: ReadingActivityAttributes.ContentState(isFinished: true),
                staleDate: nil
            )
            await activity.end(finalContent, dismissalPolicy: .immediate)
        }
    }
}
```

### Приложение: `SlumpyApp.swift` (подключение)

`ContentView` — это ваш главный экран. `SlumpySays` — временная заглушка: замените её на вашего Slumpy.

```swift
import SwiftUI

@main
struct SlumpyApp: App {
    @State private var readingSessions = ReadingSessionController()
    @Environment(\.scenePhase) private var scenePhase

    var body: some Scene {
        WindowGroup {
            ContentView()
                .environment(readingSessions)
                .overlay(alignment: .bottom) {
                    if let line = readingSessions.announcement {
                        SlumpySays(line) { readingSessions.dismissAnnouncement() }
                    }
                }
        }
        .onChange(of: scenePhase, initial: true) { _, phase in
            guard phase == .active else { return }
            Task { await readingSessions.reconcile() }
        }
    }
}

/// Заглушка: подставьте сюда вашего Slumpy с его репликой.
struct SlumpySays: View {
    let line: String
    let onDismiss: () -> Void

    init(_ line: String, onDismiss: @escaping () -> Void) {
        self.line = line
        self.onDismiss = onDismiss
    }

    var body: some View {
        Button(action: onDismiss) {
            Text(line)
                .font(.headline)
                .padding()
                .background(.regularMaterial, in: .capsule)
        }
        .buttonStyle(.plain)
        .padding()
        .accessibilityHint("Скрыть")
    }
}
```

