### Общий модуль: `ReadingSession.swift`

```swift
import Foundation

/// Одна сессия чтения. Журнал сессий пишет только приложение; расширения его только читают.
public struct ReadingSession: Codable, Sendable, Equatable, Identifiable {
    public let id: UUID
    public let startedAt: Date
    public let plannedDuration: TimeInterval
    /// Пользователь остановил сессию раньше срока.
    public internal(set) var stoppedAt: Date?
    /// Slumpy уже сказал «Сессия окончена» об этой сессии.
    public internal(set) var announcedAt: Date?

    public init(id: UUID = UUID(), startedAt: Date, plannedDuration: TimeInterval) {
        self.id = id
        self.startedAt = startedAt
        self.plannedDuration = plannedDuration
    }

    public var endsAt: Date { startedAt.addingTimeInterval(plannedDuration) }

    public func isRunning(at now: Date) -> Bool { stoppedAt == nil && now < endsAt }

    /// Дочитана до конца таймера. Окончание не записывается, а выводится из времени:
    /// результат один и тот же, кто бы и когда бы ни заметил конец сессии.
    public func isCompleted(at now: Date) -> Bool { stoppedAt == nil && now >= endsAt }

    /// Минуты для дневной цели: пока сессия идёт — 0, после — прочитанные целые минуты.
    public func creditedMinutes(at now: Date) -> Int {
        let readSeconds: TimeInterval
        if let stoppedAt {
            readSeconds = min(stoppedAt.timeIntervalSince(startedAt), plannedDuration)
        } else if now >= endsAt {
            readSeconds = plannedDuration
        } else {
            return 0
        }
        return max(0, Int(readSeconds / 60))
    }
}
```

### Общий модуль: `SessionLog.swift`

```swift
import Foundation

/// Журнал сессий: из него выводятся текущая сессия, минуты за день и реплика Slumpy.
public struct SessionLog: Codable, Sendable, Equatable {
    /// В порядке начала; идти может только последняя.
    public private(set) var sessions: [ReadingSession]

    public init(sessions: [ReadingSession] = []) { self.sessions = sessions }

    public func runningSession(at now: Date) -> ReadingSession? {
        guard let last = sessions.last, last.isRunning(at: now) else { return nil }
        return last
    }

    /// Минуты в дневную цель. Сессия засчитывается в день, когда началась.
    public func minutesRead(onDayOf day: Date, calendar: Calendar, now: Date) -> Int {
        sessions
            .filter { calendar.isDate($0.startedAt, inSameDayAs: day) }
            .reduce(0) { $0 + $1.creditedMinutes(at: now) }
    }

    /// Сессия, закончившаяся по таймеру, о которой Slumpy ещё не сказал.
    public func pendingAnnouncement(at now: Date) -> ReadingSession? {
        guard let last = sessions.last, last.isCompleted(at: now), last.announcedAt == nil else { return nil }
        return last
    }

    /// Решение расширения, когда кончился интервал сессии `sessionID`:
    /// снимать блокировку, если сейчас не идёт другая, более новая сессия.
    public func shouldClearShield(whenIntervalEndsFor sessionID: UUID, at now: Date) -> Bool {
        guard let running = runningSession(at: now) else { return true }
        return running.id == sessionID
    }

    /// Возвращает false, если уже идёт другая сессия.
    @discardableResult
    public mutating func begin(_ session: ReadingSession) -> Bool {
        guard runningSession(at: session.startedAt) == nil else { return false }
        sessions.append(session)
        return true
    }

    public mutating func stop(sessionID: UUID, at now: Date) {
        guard let index = sessions.firstIndex(where: { $0.id == sessionID }),
              sessions[index].isRunning(at: now) else { return }
        sessions[index].stoppedAt = now
    }

    public mutating func markAnnounced(sessionID: UUID, at now: Date) {
        guard let index = sessions.firstIndex(where: { $0.id == sessionID }),
              sessions[index].announcedAt == nil else { return }
        sessions[index].announcedAt = now
    }
}
```

### Общий модуль: `SessionLogStore.swift`

```swift
import Foundation

/// Файл журнала в общем контейнере App Group. Пишет только приложение, целиком и атомарно,
/// поэтому расширение читает либо старую, либо новую версию, но никогда не половину.
public struct SessionLogStore: Sendable {
    public let fileURL: URL

    public init(fileURL: URL) { self.fileURL = fileURL }

    public static func shared() -> SessionLogStore? {
        FileManager.default
            .containerURL(forSecurityApplicationGroupIdentifier: SlumpyShared.appGroupID)
            .map { SessionLogStore(fileURL: $0.appending(path: "reading-sessions.json")) }
    }

    /// Нет файла — пустой журнал. Битый файл — DecodingError.
    /// Недоступный (телефон ещё не разблокировали после перезагрузки) — другая ошибка.
    public func load() throws -> SessionLog {
        let data: Data
        do {
            data = try Data(contentsOf: fileURL)
        } catch let error as CocoaError where error.code == .fileReadNoSuchFile {
            return SessionLog()
        }
        return try JSONDecoder().decode(SessionLog.self, from: data)
    }

    public func save(_ log: SessionLog) throws {
        let data = try JSONEncoder().encode(log)
        // Расширение срабатывает и на заблокированном телефоне: файл должен читаться после первой разблокировки.
        try data.write(to: fileURL, options: [.atomic, .completeFileProtectionUntilFirstUserAuthentication])
    }

    /// Откладывает нечитаемый файл в сторону вместо перезаписи, чтобы историю можно было восстановить.
    public func moveAsideUnreadableFile(now: Date = .now) {
        let backup = fileURL.deletingPathExtension()
            .appendingPathExtension("unreadable-\(Int(now.timeIntervalSince1970)).json")
        try? FileManager.default.moveItem(at: fileURL, to: backup)
    }
}
```

