import Foundation
#if os(iOS)
import ActivityKit
import DeviceActivity
import ManagedSettings
#endif

public enum SlumpyShared {
    /// Должен совпадать с App Group у приложения, расширения и виджета.
    public static let appGroupID = "group.app.slumpy"
}

#if os(iOS)
extension ManagedSettingsStore.Name {
    /// Блокировка на время чтения. Отдельное хранилище: её снятие не задевает другие ограничения.
    public static var readingSession: Self { Self("readingSession") }
}

public enum ReadingShield {
    public static func clear() {
        ManagedSettingsStore(named: .readingSession).clearAllSettings()
    }
}

/// Своё имя расписания у каждой сессии: запоздавший конец старой сессии не спутать с новой.
public enum ReadingMonitor {
    private static let prefix = "reading."

    public static func name(for sessionID: UUID) -> DeviceActivityName {
        DeviceActivityName(prefix + sessionID.uuidString)
    }

    public static func sessionID(from name: DeviceActivityName) -> UUID? {
        guard name.rawValue.hasPrefix(prefix) else { return nil }
        return UUID(uuidString: String(name.rawValue.dropFirst(prefix.count)))
    }
}

public struct ReadingActivityAttributes: ActivityAttributes, Sendable {
    public struct ContentState: Codable, Hashable, Sendable {
        public var isFinished: Bool
        public init(isFinished: Bool) { self.isFinished = isFinished }
    }

    public let startedAt: Date
    public let endsAt: Date

    public init(startedAt: Date, endsAt: Date) {
        self.startedAt = startedAt
        self.endsAt = endsAt
    }
}
