import Foundation
import SlumpyCore
import Testing

struct ReadingSessionEndTests {
    private let calendar: Calendar = {
        var calendar = Calendar(identifier: .gregorian)
        calendar.timeZone = TimeZone(identifier: "Europe/Moscow")!
        return calendar
    }()

    private func date(_ day: Int, _ hour: Int, _ minute: Int) -> Date {
        calendar.date(from: DateComponents(year: 2026, month: 10, day: day, hour: hour, minute: minute))!
    }

    private func session(at start: Date) -> ReadingSession {
        ReadingSession(startedAt: start, plannedDuration: 30 * 60)
    }

    @Test func minutesCountTowardTodayOnlyWhenTheTimerEnds() {
        var log = SessionLog()
        log.begin(session(at: date(28, 21, 0)))
        #expect(log.minutesRead(onDayOf: date(28, 12, 0), calendar: calendar, now: date(28, 21, 29)) == 0)
        #expect(log.minutesRead(onDayOf: date(28, 12, 0), calendar: calendar, now: date(28, 21, 30)) == 30)
    }

    @Test func sessionCrossingMidnightCountsForTheDayItStarted() {
        var log = SessionLog()
        log.begin(session(at: date(28, 23, 50)))
        let after = date(29, 0, 30)
        #expect(log.minutesRead(onDayOf: date(28, 12, 0), calendar: calendar, now: after) == 30)
        #expect(log.minutesRead(onDayOf: date(29, 12, 0), calendar: calendar, now: after) == 0)
    }

    @Test func earlyStopCountsWholeMinutesReadAndSlumpyStaysQuiet() {
        var log = SessionLog()
        let reading = session(at: date(28, 21, 0))
        log.begin(reading)
        log.stop(sessionID: reading.id, at: date(28, 21, 12).addingTimeInterval(40))
        let later = date(28, 22, 0)
        #expect(log.minutesRead(onDayOf: later, calendar: calendar, now: later) == 12)
        #expect(log.pendingAnnouncement(at: later) == nil)
    }

    @Test func slumpyAnnouncesTheEndOnce() {
        var log = SessionLog()
        let reading = session(at: date(28, 21, 0))
        log.begin(reading)
        #expect(log.pendingAnnouncement(at: date(28, 21, 10)) == nil)
        let opened = date(28, 23, 0)
        #expect(log.pendingAnnouncement(at: opened)?.id == reading.id)
        log.markAnnounced(sessionID: reading.id, at: opened)
        #expect(log.pendingAnnouncement(at: date(28, 23, 5)) == nil)
    }

